import json
import logging.config
import os
from time import gmtime

from ute_common_abstract_core import logger as core_logger


class ExtendedFormatter(logging.Formatter):
    """Common formatter extension settings"""
    default_msec_format = '%s,%03dZ'
    default_time_format = "%Y-%m-%dT%H:%M:%S"
    converter = gmtime


class JSONFormatter(ExtendedFormatter):
    """
    A basic custom JSON formatter for the standard logging module.

    `std_keys` is a set of keys that are present in every LogRecord object, by default they are not included in the
    JSON output. This is to use only custom keys in the JSON output (except for the timestamp).
    :param include_std_keys: list of standard logging keys to include in the JSON output
    """
    std_keys = {'name', 'args', 'msg', 'levelname', 'levelno', 'pathname', 'filename', 'module', 'lineno', 'funcName',
                'created', 'msecs', 'relativeCreated', 'thread', 'threadName', 'process', 'processName', 'exc_info',
                'exc_text', 'stack_info'}

    def __init__(self, include_std_keys: list = None):
        if include_std_keys is None:
            include_std_keys = []
        self._exclude_std_keys = set()
        self._exclude_std_keys.update(self.std_keys)
        super().__init__()
        for key in include_std_keys:
            self._exclude_std_keys.remove(key)

    def format(self, record):
        log_record = {
            'timestamp': self.formatTime(record, self.datefmt),
            'message': record.getMessage(),
        }
        # Add all attributes from the LogRecord object to the log_record dictionary
        for key in record.__dict__:
            if key not in self._exclude_std_keys:
                log_record[key] = getattr(record, key)
        return json.dumps(log_record)


def create_logger(name, log_file, log_level=core_logger.TRACE, log_format="%(asctime)s %(levelname)-10s: |%(message)s",
                  datefmt=None):
    """
    Create Logger with file writer.

    :param name: Logger name
    :param log_file: Path to logfile. This path is added to logging_path variable. Final logfile location is logging_path + log_file
    :param log_level: only log records with equal and greater level will be accepted for storage in log
    :param log_format: layout of log file, default is "%(asctime)s %(levelname)-10s: |%(message)s"
    :return: None
    """
    logger = logging.getLogger(name)
    if name not in core_logger.active_loggers:
        logger.setLevel(log_level)
        logfile_full_path = os.path.join(core_logger.logging_path, log_file)
        core_logger._prepare_logs_folder(logfile_full_path)
        core_logger.setup_new_file_handler(logger_name=name,
                                           log_level=log_level,
                                           log_filename=logfile_full_path,
                                           formatter=ExtendedFormatter(fmt=log_format, datefmt=datefmt))
        core_logger.append_additional_handlers(logger_name=name)
        core_logger.active_loggers.append(name)
    return logger


def create_json_logger(name, log_file, log_level=core_logger.TRACE):
    """
    Create JSON Logger with file writer.

    :param name: Logger name
    :param log_file: Path to logfile. This path is added to logging_path variable. Final logfile location is logging_path + log_file
    :param log_level: only log records with equal and greater level will be accepted for storage in log
    :return: None
    """
    logger = logging.getLogger(name)
    if name not in core_logger.active_loggers:
        logger.setLevel(log_level)
        logfile_full_path = os.path.join(core_logger.logging_path, log_file)
        core_logger._prepare_logs_folder(logfile_full_path)
        core_logger.setup_new_file_handler(logger_name=name,
                                           log_level=log_level,
                                           log_filename=logfile_full_path,
                                           formatter=JSONFormatter())
        core_logger.append_additional_handlers(logger_name=name)
        core_logger.active_loggers.append(name)

        # Wrap the logger methods to include the custom_key1 parameter
        original_info = logger.info

        def info(msg, *args, **kwargs):
            original_info(msg, extra=kwargs, *args)

        logger.info = info
    return logger


def configure_config_logger():
    """Configure logger with file storing configuration's log"""
    logger = create_logger(name='al.config',
                           log_file='al.config.log',
                           log_level=core_logger.TRACE,
                           log_format="%(asctime)s %(levelname)-10s |%(message)s",
                           datefmt=None)
    logger.propagate = False


